import java.util.*;

class Solution {
  private int[] nums, target;
  private int n, k;
  private int[][] memo;
  private static final int INF = 1_000_000_000;

  public int minimumValueSum(int[] nums, int[] andValues) {
    this.nums = nums;
    this.target = andValues;
    n = nums.length;
    k = andValues.length;
    memo = new int[n + 1][k + 1];
    for (int[] row : memo) Arrays.fill(row, -1);
    int ans = dfs(0, 0);
    return ans >= INF ? -1 : ans;
  }

  private int dfs(int start, int group) {
    if (group == k) return start == n ? 0 : INF;
    if (n - start < k - group) return INF;
    if (memo[start][group] != -1) return memo[start][group];
    int value = -1, best = INF;
    int lastEnd = n - (k - group - 1);
    for (int end = start; end < lastEnd; end++) {
      value &= nums[end];
      if (value == target[group]) {
        int next = dfs(end + 1, group + 1);
        if (next < INF) best = Math.min(best, nums[end] + next);
      }
    }
    return memo[start][group] = best;
  }
}
